/**
 * Rewrites in-body <img> tags for local raster images into <picture> elements
 * with AVIF + WebP srcset variants generated by scripts/optimize-images.mjs.
 *
 * Falls back to a plain <img> when the image has no manifest entry (remote
 * images, SVGs, unreferenced assets), so nothing breaks if the pipeline is
 * bypassed.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const MANIFEST_PATH = path.join(here, '../generated/inline-images.json');

let manifestCache = null;
function loadManifest() {
  if (manifestCache) return manifestCache;
  try {
    manifestCache = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
  } catch {
    manifestCache = {};
  }
  return manifestCache;
}

const SIZES = '(min-width: 800px) 720px, 100vw';

function srcset(variants, key) {
  return variants.map((v) => `${v[key]} ${v.w}w`).join(', ');
}

export function rehypeResponsiveImages() {
  return (tree) => {
    const manifest = loadManifest();
    walk(tree, manifest);
  };
}

function walk(node, manifest) {
  if (!node || !Array.isArray(node.children)) return;
  for (let i = 0; i < node.children.length; i++) {
    const child = node.children[i];
    if (child?.type === 'element' && child.tagName === 'img') {
      const replacement = toPicture(child, manifest);
      if (replacement) {
        node.children[i] = replacement;
        continue;
      }
    }
    walk(child, manifest);
  }
}

function toPicture(img, manifest) {
  const props = img.properties ?? {};
  const rawSrc = props.src;
  if (typeof rawSrc !== 'string') return null;
  let src = rawSrc;
  try {
    src = decodeURIComponent(new URL(rawSrc, 'https://local.invalid').pathname);
  } catch {
    return null;
  }
  const entry = manifest[src];
  if (!entry || !Array.isArray(entry.variants) || entry.variants.length === 0) return null;

  // The original PNG/JPEG stays in public/ for direct links; the fallback
  // <img> points at the largest WebP variant so no request is ever served the
  // multi-hundred-KB source file.
  const fallback = entry.variants[entry.variants.length - 1];
  const base = {
    type: 'element',
    tagName: 'img',
    properties: {
      ...props,
      src: fallback.webp,
      width: props.width ?? entry.width,
      height: props.height ?? entry.height,
      loading: props.loading ?? 'lazy',
      decoding: props.decoding ?? 'async',
    },
    children: [],
  };

  const sources = [
    {
      type: 'element',
      tagName: 'source',
      properties: { type: 'image/avif', srcSet: srcset(entry.variants, 'avif'), sizes: SIZES },
      children: [],
    },
    {
      type: 'element',
      tagName: 'source',
      properties: { type: 'image/webp', srcSet: srcset(entry.variants, 'webp'), sizes: SIZES },
      children: [],
    },
  ];

  return { type: 'element', tagName: 'picture', properties: {}, children: [...sources, base] };
}
